const entrada = $input.first();
const body = (entrada && entrada.json && entrada.json.body) || {};
const out = [];

for (const entry of body.entry || []) {
  // Comentários
  for (const ch of entry.changes || []) {
    const v = ch.value || {};
    if (ch.field === 'comments' && v.id) {
      out.push({ json: {
        tipo: 'comentario',
        comment_id: v.id,
        texto: v.text || '',
        autor: (v.from && v.from.username) || '',
        autor_id: (v.from && v.from.id) || '',
        media_id: (v.media && v.media.id) || ''
      } });
    }
  }
  // Directs
  for (const m of entry.messaging || []) {
    if (m.message && m.message.text && !m.message.is_echo) {
      out.push({ json: {
        tipo: 'dm',
        sender_id: m.sender && m.sender.id,
        texto: m.message.text,
        autor: '',
        autor_id: (m.sender && m.sender.id) || ''
      } });
    }
  }
}

// Não responde a si mesmo
return out.filter(o => String(o.json.autor_id) !== String($env.IG_USER_ID || ''));

const ev = $('Normalizar evento').first().json;
const resp = $('Atendente IA').first().json.output;
return [{ json: {
  quando: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
  tipo: ev.tipo,
  autor: ev.autor || ev.autor_id || '',
  mensagem: ev.texto,
  resposta: resp
} }];

const ev = $('Normalizar evento').item.json;
const linhas = ($('Planilha: achar o post').item.json || {}).values || [];
const cab = linhas[0] || [];
const iPost = cab.indexOf('post_id');
const iProd = cab.indexOf('produto');
const iLink = cab.indexOf('link');

let produto = '', link = '', origem = '';

// 1) O comentario veio de um post que a automacao publicou: a planilha sabe qual e.
if (ev.media_id && iPost >= 0) {
  const l = linhas.find((r, k) => k > 0 && String(r[iPost] || '') === String(ev.media_id));
  if (l) { produto = l[iProd] || ''; link = l[iLink] || ''; origem = 'planilha'; }
}

// 2) A pessoa escreveu a palavra-chave que esta queimada no video
//    ("RESPONDE ESSA STORY COM MANTIMENTOS"). Resposta de story chega
//    como direct, sem referencia ao post, entao e por aqui que ela resolve.
if (!produto) {
  const txt = String(ev.texto || '').trim();
  if (/^[A-Za-zÀ-ÿ]{3,20}$/.test(txt)) {
    const chave = txt.toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    // O raw do GitHub vem como text/plain, entao o n8n nao desserializa:
    // chega {data: '<json>'}. Aceita as duas formas.
    let mapa = $('Palavras do calendário').item.json || {};
    if (typeof mapa.data === 'string') {
      try { mapa = JSON.parse(mapa.data); } catch (e) { mapa = {}; }
    }
    let achado = mapa[chave] ? chave : '';

    // Quem digita a palavra que viu no video erra letra. Aceita a
    // palavra mais proxima, desde que seja UMA so: havendo empate,
    // prefere cair no catalogo a chutar o produto errado.
    if (!achado && chave.length >= 5) {
      const dist = (a, b) => {
        const l = Array.from({ length: b.length + 1 }, (_, i) => i);
        for (let i = 1; i <= a.length; i++) {
          let ant = l[0];
          l[0] = i;
          for (let j = 1; j <= b.length; j++) {
            const tmp = l[j];
            l[j] = Math.min(l[j] + 1, l[j - 1] + 1, ant + (a[i - 1] === b[j - 1] ? 0 : 1));
            ant = tmp;
          }
        }
        return l[b.length];
      };
      let melhor = Infinity;
      let quais = [];
      for (const k of Object.keys(mapa)) {
        const dd = dist(chave, k);
        if (dd < melhor) { melhor = dd; quais = [k]; }
        else if (dd === melhor) quais.push(k);
      }
      const limite = chave.length >= 8 ? 2 : 1;
      if (melhor <= limite && quais.length === 1) achado = quais[0];
    }

    if (achado && mapa[achado] && mapa[achado].link) {
      produto = mapa[achado].produto || '';
      link = mapa[achado].link;
      origem = achado === chave ? 'palavra' : 'palavra-aproximada';
    }
  }
}

// 3) Post publicado a mao: nao esta na planilha, entao le a legenda do proprio post.
let legenda = '';
if (!produto) {
  const r = $('Instagram: legenda do post').item.json || {};
  if (!r.error && r.caption) legenda = String(r.caption).slice(0, 400);
}

return { json: Object.assign({}, ev, {
  post_produto: produto, post_link: link, post_legenda: legenda, post_origem: origem
}) };

// Toda resposta publica saia com a MESMA frase. Dezenas delas em
// sequencia, saindo da propria conta, lembram spam - e o alcance do
// post de 16/11 caiu para 9 contas com 17 comentarios.
// A frase passa a variar, sorteada pelo id do comentario: estavel para
// o mesmo comentario (nao muda se repetir), diferente entre comentarios.
const frases = [
  'Te mandei no direct 📩',
  'Mandei no seu direct, da uma olhada 👀',
  'Ja esta no seu direct 😉',
  'Te chamei no direct com o link 📩',
  'Olha no direct que eu te mandei ✨',
  'Acabei de mandar no seu privado 📩',
  'Respondi no seu direct, confere la 👀',
  'Link no seu direct 😉',
  'Mandei tudo no direct pra voce ✨',
  'Chegou no seu direct 📩'
];

const j = $json;
const ev = $('Normalizar evento').item.json;
const semente = String(ev.comment_id || ev.autor_id || '');
let h = 7;
for (const c of semente) h = (h * 31 + c.charCodeAt(0)) | 0;

const texto = String(j.output || '');
const temLink = /https?:\/\//.test(texto);

return { json: Object.assign({}, j, {
  resposta_publica: temLink ? frases[Math.abs(h) % frases.length] : texto
}) };
